pub fn testEventBus(alloc: std.mem.Allocator) void {
    // -- tagsMatch: containment, kinds, empty --
    const tags = [_]eb.TagValue{ eb.tagString(.TOPIC, "orders"), eb.tagInt(.KIND, 5) };
    util.check(eb.tagsMatch(alloc, &tags, &.{}), "empty filter matches");
    util.check(eb.tagsMatch(alloc, &tags, &.{eb.tagString(.TOPIC, "orders")}), "containment");
    util.check(eb.tagsMatch(alloc, &tags, &tags), "self match");
    util.check(!eb.tagsMatch(alloc, &tags, &.{eb.tagEnum(.KIND, 5)}), "int != enum");
    util.check(!eb.tagsMatch(alloc, &tags, &.{eb.tagString(.KIND, "5")}), "int != string");
    util.check(!eb.tagsMatch(alloc, &tags, &.{eb.tagString(.TOPIC, "other")}), "value mismatch");

    // -- fan-out honors filters --
    var bus: Bus = undefined;
    Bus.init(alloc, &bus);
    var orders = std.ArrayList(eb.Event).empty;
    var all_events = std.ArrayList(eb.Event).empty;
    var orders_mutex = std.Thread.Mutex{};
    var all_mutex = std.Thread.Mutex{};
    var orders_ctx = CollectCtx{
        .stream = eb.subscribeEvents(&bus.client, &.{eb.tagString(.TOPIC, "orders")}),
        .out = &orders,
        .mutex = &orders_mutex,
    };
    var all_ctx = CollectCtx{
        .stream = eb.subscribeEvents(&bus.client, &.{}),
        .out = &all_events,
        .mutex = &all_mutex,
    };
    _ = std.Thread.spawn(.{}, collectMain, .{&orders_ctx}) catch unreachable;
    _ = std.Thread.spawn(.{}, collectMain, .{&all_ctx}) catch unreachable;
    waitFor(&bus.broker, 2, "2 subscribers");
    checkEq(u64, eb.publishEvent(&bus.client, &.{eb.tagString(.TOPIC, "orders")}, "o1", "test"), 1, "seq 1");
    checkEq(u64, eb.publishEvent(&bus.client, &.{eb.tagString(.TOPIC, "other")}, "x1", "test"), 2, "seq 2");
    waitCollect(&orders, &orders_mutex, 1, "orders");
    waitCollect(&all_events, &all_mutex, 2, "all");
    util.check(std.mem.eql(u8, orders.items[0].payload, "o1"), "filtered payload");
    util.check(std.mem.eql(u8, orders.items[0].publisher_id, "test"), "publisher");
    util.check(all_events.items[0].seq == 1 and all_events.items[1].seq == 2, "all seqs");

    // -- kinds never cross-match --
    var bus2: Bus = undefined;
    Bus.init(alloc, &bus2);
    var got = std.ArrayList(eb.Event).empty;
    var got_mutex = std.Thread.Mutex{};
    var got_ctx = CollectCtx{
        .stream = eb.subscribeEvents(&bus2.client, &.{eb.tagInt(.KIND, 5)}),
        .out = &got,
        .mutex = &got_mutex,
    };
    _ = std.Thread.spawn(.{}, collectMain, .{&got_ctx}) catch unreachable;
    waitFor(&bus2.broker, 1, "kind subscriber");
    _ = eb.publishEvent(&bus2.client, &.{eb.tagString(.KIND, "5")}, "s", "");
    _ = eb.publishEvent(&bus2.client, &.{eb.tagEnum(.KIND, 5)}, "e", "");
    checkEq(u64, eb.publishEvent(&bus2.client, &.{eb.tagInt(.KIND, 5)}, "i", ""), 3, "seq 3");
    waitCollect(&got, &got_mutex, 1, "kind match");
    util.check(std.mem.eql(u8, got.items[0].payload, "i"), "int kind only");

    // (No user-tag pass-through leg: the generated Tag is a
    // closed Zig enum; see eventbus.zig. Own tags arrive by
    // regenerating from an extended events.proto copy.)

    // -- slow subscriber drops oldest --
    var broker4 = eb.EventBusBroker.init(alloc, 4);
    var sub = broker4.subscribeLocal(&.{});
    var i: usize = 1;
    while (i <= 6) : (i += 1) {
        const payload = std.fmt.allocPrint(alloc, "m{d}", .{i}) catch unreachable;
        _ = broker4.publishEvent(&.{}, payload, "");
    }
    checkEq(i64, broker4.droppedTotal(), 2, "dropped count");
    checkEq(usize, sub.dropped(), 2, "sub dropped");
    const want_seqs = [_]u64{ 3, 4, 5, 6 };
    for (want_seqs) |want| {
        checkEq(u64, sub.take(1000).?.seq, want, "kept newest");
    }
    sub.close();
    checkEq(usize, broker4.subscriberCount(), 0, "close unregisters");

    // -- close unsubscribes (RPC) --
    var bus5: Bus = undefined;
    Bus.init(alloc, &bus5);
    var stream5 = eb.subscribeEvents(&bus5.client, &.{});
    waitFor(&bus5.broker, 1, "1 subscriber");
    _ = eb.publishEvent(&bus5.client, &.{}, "a", "");
    switch (stream5.recv()) {
        .message => |ev| util.check(std.mem.eql(u8, ev.payload, "a"), "recv before close"),
        else => util.check(false, "recv before close"),
