    stream5.stream.cancel();
    _ = eb.publishEvent(&bus5.client, &.{}, "b", "");
    waitFor(&bus5.broker, 0, "reaped");

    // -- git log round-trip + idempotent --
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const repo = tmp.dir.realpathAlloc(alloc, ".") catch unreachable;
    var broker6 = eb.EventBusBroker.init(alloc, eb.subscriber_queue_capacity);
    const events = [_]eb.Event{
        broker6.publishEvent(&.{eb.tagString(.TOPIC, "orders")}, "o1", "test"),
        broker6.publishEvent(&.{eb.tagString(.TOPIC, "other")}, "x1", "test"),
        broker6.publishEvent(&.{eb.tagString(.TOPIC, "orders")}, "o2", "test"),
    };
    const head1 = ebgit.exportEvents(alloc, repo, &events, ebgit.event_log_branch) catch unreachable;
    const count = ebgit.gitText(alloc, repo, &.{ "rev-list", "--count", "grpc-dc-events" }, null, null) catch unreachable;
    util.check(std.mem.eql(u8, count, "3"), "commit count");
    const head2 = ebgit.exportEvents(alloc, repo, &events, ebgit.event_log_branch) catch unreachable;
    util.check(std.mem.eql(u8, head2.?, head1.?), "idempotent re-export");
    const imported = ebgit.importEvents(alloc, repo, ebgit.event_log_branch, 0, null, null) catch unreachable;
    util.check(imported.items.len == 3 and imported.items[0].seq == 1 and imported.items[2].seq == 3, "import seqs");
    util.check(std.mem.eql(u8, imported.items[0].payload, "o1") and std.mem.eql(u8, imported.items[2].payload, "o2"), "import payloads");
    const filtered = ebgit.importEvents(alloc, repo, ebgit.event_log_branch, 0, null, &.{eb.tagString(.TOPIC, "orders")}) catch unreachable;
    util.check(filtered.items.len == 2 and filtered.items[1].seq == 3, "import filter");
    const window = ebgit.importEvents(alloc, repo, ebgit.event_log_branch, 1, 2, null) catch unreachable;
    util.check(window.items.len == 1 and window.items[0].seq == 2, "import window");

    std.debug.print("TestEventBus OK\n", .{});
}
